      "source_ids": ["A1"]
    },
    {
      "title": "西伯利亚古墓发现2800年前大麻使用证据",
      "summary": "科学家在2800年前西伯利亚墓中发现约1000粒大麻种子和化学证据，表明古代斯基泰人使用其致幻效果，为最早直接测年的精神活性大麻使用考古证据。",
      "source_ids": ["A7"]
    },
    {
      "title": "科科斯群岛发现绵延逾1.5公里珊瑚群体",
      "summary": "研究人员在科科斯（基林）群岛外礁识别出绵延逾1.5公里的巨大珊瑚群体，为已知最大珊瑚群体之一。",
      "source_ids": ["A8"]
    },
    {
      "title": "新研究：睡眠障碍关联大脑结构变化",
      "summary": "基于57项脑成像研究，科学家发现睡眠障碍与控制注意力、决策和情绪的大脑区域结构变化相关，或解释睡眠紊乱影响日常思维行为。",
      "source_ids": ["A10"]
    },
    {
      "title": "弗洛勒斯人同洞穴发现最大地栖鸟类新种",
      "summary": "研究人员在弗洛勒斯岛梁布阿洞穴发现一种新的地栖鸟类，化石距今19万至12万年，与弗洛勒斯人同洞穴，为同类中最大。",
      "source_ids": ["A11"]
    },
    {
      "title": "科学家制造持续300阿秒的破纪录X射线闪光",
      "summary": "科学家创造持续仅300阿秒的破纪录X射线闪光，将巨大功率集中在极小区域，有望用于观察电子运动并控制化学反应超快过程。",
      "source_ids": ["A12"]
    },
    {
      "title": "研究排除“极其巨大”原初黑洞作为暗物质来源",
      "summary": "研究称，若原初黑洞存在，其起源不同于恒星坍缩黑洞；一些理论认为“极其巨大”原初黑洞可解释大量暗物质，但新研究将其排除。",
      "source_ids": ["A15"]
    },
    {
      "title": "研究：核爆偏转小行星效果随角度差近五倍",
      "summary": "新研究显示，小行星不规则形状会显著影响X射线爆炸的偏转效果，不同角度下有效性相差近五倍。核爆或可拯救地球，但打错面可能失败。",
      "source_ids": ["A3"]
    }
  ]
}

